create table d_trd_otc_contr_props(key_otc_trade_id string comment 'trs合约id ',property_name string comment 'trs合约属性 ',property_value string comment 'trs合约属性值 ',created_datetime string comment '创建时间 ',created_by string comment '创建人 ',updated_datetime string comment '修改时间 ',updated_by string comment '修改人 ',data_time string comment '【AI】数据时间') partitioned by (busi_date string) row format delimited fields terminated by ',' stored as textfile;
